import { useEffect, useMemo, useState } from 'react';
import { FaDownload, FaPrint, FaSave, FaSyncAlt, FaUserGraduate } from 'react-icons/fa';
import { Trash2 } from 'lucide-react';
import SectionHeader from '../ui/SectionHeader.jsx';
import IconActionButton from '../ui/IconActionButton.jsx';
import SearchFilter from '../forms/SearchFilter.jsx';
import FormField from '../forms/FormField.jsx';
import InfoCard from '../ui/InfoCard.jsx';
import StatusBadge from '../ui/StatusBadge.jsx';
import { ATTENDANCE_STATUSES, bulkCreateAttendance, deleteAttendance, getAttendanceHistory, getAttendanceSummary, getDefaultAttendanceValues, listAttendance } from '../../services/attendanceService.js';
import { createLeave, listLeaves } from '../../services/leaveService.js';
import { buildAttendanceCsv, getAttendanceReport } from '../../services/attendanceReportService.js';

const statusOptions = [
  { value: 'All', label: 'All statuses' },
  ...ATTENDANCE_STATUSES.map((status) => ({ value: status, label: status })),
];

const reportModes = ['Daily', 'Monthly', 'Subject-wise', 'Student Summary', 'Faculty Summary', 'Low Attendance Report'];

function formatCurrency(value) {
  return `$${Number(value || 0).toLocaleString()}`;
}

function getStatusClass(status) {
  switch (status) {
    case 'Present':
      return 'bg-emerald-500/15 text-emerald-700';
    case 'Absent':
      return 'bg-rose-500/15 text-rose-700';
    case 'Late':
      return 'bg-amber-500/15 text-amber-700';
    case 'Half Day':
      return 'bg-sky-500/15 text-sky-700';
    case 'Leave':
      return 'bg-indigo-500/15 text-indigo-700';
    case 'Medical Leave':
      return 'bg-purple-500/15 text-purple-700';
    case 'Holiday':
      return 'bg-slate-500/15 text-slate-700';
    case 'Online':
      return 'bg-cyan-500/15 text-cyan-700';
    default:
      return 'bg-slate-200/80 text-slate-700';
  }
}

export default function AttendanceModule({
  scope = 'student',
  title = 'Attendance management',
  subtitle = 'Capture attendance efficiently and keep records audit-ready.',
  entityLabel = 'student',
  entityPlaceholder = 'Aarav Sharma',
}) {
  const [records, setRecords] = useState([]);
  const [summary, setSummary] = useState({
    todaysEntries: 0,
    presentCount: 0,
    absentCount: 0,
    lateCount: 0,
    attendancePercentage: 0,
    lowAttendanceAlerts: 0,
    facultyAttendance: 0,
  });
  const [history, setHistory] = useState([]);
  const [leaves, setLeaves] = useState([]);
  const [draftEntries, setDraftEntries] = useState([]);
  const [sessionValues, setSessionValues] = useState(getDefaultAttendanceValues(scope));
  const [filters, setFilters] = useState({ query: '', status: 'All', department: 'All', course: 'All', semester: 'All', subject: 'All', faculty: 'All', dateFrom: '', dateTo: '' });
  const [reportMode, setReportMode] = useState('Daily');
  const [statusMessage, setStatusMessage] = useState('Auto-save enabled');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const draftKey = `${scope}-attendance-draft`;

  const loadAttendanceData = async () => {
    setIsLoading(true);
    const [attendanceResponse, leaveResponse, summaryResponse, historyResponse] = await Promise.all([
      listAttendance(scope, filters),
      listLeaves(),
      getAttendanceSummary(scope),
      getAttendanceHistory(scope, filters.query || ''),
    ]);
    setRecords(attendanceResponse.items || []);
    setLeaves(leaveResponse.items || []);
    setSummary(summaryResponse);
    setHistory(historyResponse.items || []);
    const savedDraft = typeof window !== 'undefined' ? window.localStorage.getItem(draftKey) : null;
    if (savedDraft) {
      try {
        const parsedDraft = JSON.parse(savedDraft);
        if (Array.isArray(parsedDraft)) {
          setDraftEntries(parsedDraft);
        }
      } catch {
        setDraftEntries([]);
      }
    } else if (!draftEntries.length && (attendanceResponse.items || []).length) {
      setDraftEntries((attendanceResponse.items || []).slice(0, 8).map((entry) => ({
        id: entry.id,
        name: entry.studentName || entry.teacherName || entry.employeeName || entry.guardName || '',
        status: entry.status || 'Present',
        remarks: entry.remarks || '',
        subject: entry.subject || '',
        date: entry.date || sessionValues.date,
      })));
    }
    setIsLoading(false);
  };

  useEffect(() => {
    loadAttendanceData();
  }, [scope]);

  useEffect(() => {
    if (typeof window !== 'undefined' && draftEntries.length) {
      window.localStorage.setItem(draftKey, JSON.stringify(draftEntries));
      setStatusMessage('Draft auto-saved');
    }
  }, [draftEntries, draftKey]);

  const filteredRecords = useMemo(() => {
    return records.filter((entry) => {
      const query = filters.query.trim().toLowerCase();
      const searchable = [
        entry.studentId,
        entry.studentName,
        entry.teacherName,
        entry.employeeName,
        entry.guardName,
        entry.department,
        entry.course,
        entry.semester,
        entry.subject,
        entry.faculty,
        entry.date,
        entry.status,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      const matchesQuery = !query || searchable.includes(query);
      const matchesStatus = filters.status === 'All' || entry.status === filters.status;
      const matchesDepartment = filters.department === 'All' || entry.department === filters.department;
      const matchesCourse = filters.course === 'All' || entry.course === filters.course;
      const matchesSemester = filters.semester === 'All' || entry.semester === filters.semester;
      const matchesSubject = filters.subject === 'All' || entry.subject === filters.subject;
      const matchesFaculty = filters.faculty === 'All' || entry.faculty === filters.faculty;
      const matchesDateFrom = !filters.dateFrom || entry.date >= filters.dateFrom;
      const matchesDateTo = !filters.dateTo || entry.date <= filters.dateTo;
      return matchesQuery && matchesStatus && matchesDepartment && matchesCourse && matchesSemester && matchesSubject && matchesFaculty && matchesDateFrom && matchesDateTo;
    });
  }, [records, filters]);

  const subjectBreakdown = useMemo(() => {
    return records.reduce((accumulator, entry) => {
      const subject = entry.subject || 'Unassigned';
      if (!accumulator[subject]) {
        accumulator[subject] = { present: 0, absent: 0, total: 0 };
      }
      accumulator[subject].total += 1;
      if (entry.status === 'Present') accumulator[subject].present += 1;
      if (entry.status === 'Absent') accumulator[subject].absent += 1;
      return accumulator;
    }, {});
  }, [records]);

  const reportRows = useMemo(() => {
    const items = filteredRecords.length ? filteredRecords : records;
    switch (reportMode) {
      case 'Monthly':
        return items.filter((entry) => entry.date >= new Date().toISOString().slice(0, 7));
      case 'Subject-wise':
        return items.filter((entry) => entry.subject);
      case 'Student Summary':
        return items.filter((entry) => entry.studentName || entry.studentId);
      case 'Faculty Summary':
        return items.filter((entry) => entry.faculty || entry.teacherName);
      case 'Low Attendance Report':
        return items.filter((entry) => entry.status === 'Absent' || entry.status === 'Leave' || entry.status === 'Medical Leave');
      default:
        return items.filter((entry) => entry.date === sessionValues.date);
    }
  }, [filteredRecords, records, reportMode, sessionValues.date]);

  const handleFieldChange = (event) => {
    const { name, value } = event.target;
    setSessionValues((current) => ({ ...current, [name]: value }));
  };

  const updateDraftStatus = (id, status) => {
    setDraftEntries((current) => current.map((entry) => (entry.id === id ? { ...entry, status } : entry)));
  };

  const handleMarkAllPresent = () => {
    setDraftEntries((current) => current.map((entry) => ({ ...entry, status: 'Present' })));
  };

  const handleQuickToggle = () => {
    setDraftEntries((current) => current.map((entry) => ({ ...entry, status: entry.status === 'Present' ? 'Absent' : 'Present' })));
  };

  const handleBulkAttendance = () => {
    setDraftEntries((current) => current.map((entry) => ({ ...entry, status: 'Present' })));
    setStatusMessage('Bulk attendance prepared for review');
  };

  const handleSubmitAttendance = async () => {
    setIsSubmitting(true);
    try {
      const payloads = draftEntries.map((entry) => ({ ...sessionValues, ...entry, status: entry.status || 'Present', date: entry.date || sessionValues.date }));
      await bulkCreateAttendance(scope, payloads);
      setDraftEntries([]);
      window.localStorage.removeItem(draftKey);
      await loadAttendanceData();
      setStatusMessage('Attendance submitted and audit logged');
    } catch {
      setStatusMessage('Unable to submit attendance right now');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteRecord = async (id) => {
    await deleteAttendance(scope, id);
    await loadAttendanceData();
  };

  const handleCreateLeave = async (event) => {
    event.preventDefault();
    const leavePayload = {
      studentId: sessionValues.studentId || '',
      studentName: sessionValues.studentName || '',
      department: sessionValues.department || '',
      subject: sessionValues.subject || '',
      status: 'Pending',
      reason: 'Requested via attendance workspace',
      dateFrom: sessionValues.date,
      dateTo: sessionValues.date,
    };
    await createLeave(leavePayload);
    await loadAttendanceData();
  };

  const handleExport = async (type) => {
    const report = await getAttendanceReport(scope, { ...filters, status: filters.status === 'All' ? '' : filters.status });
    const blob = type === 'excel' ? buildAttendanceCsv(report.exportRows) : buildAttendanceCsv(report.exportRows);
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `${scope}-attendance.${type === 'excel' ? 'xlsx' : 'csv'}`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  const handlePrint = () => window.print();

  const summaryCards = [
    { title: 'Today attendance', value: `${summary.todaysEntries} entries` },
    { title: 'Absent students', value: summary.absentCount },
    { title: 'Late students', value: summary.lateCount },
    { title: 'Attendance %', value: `${summary.attendancePercentage}%` },
    { title: 'Low attendance alerts', value: summary.lowAttendanceAlerts },
    { title: 'Faculty attendance', value: summary.facultyAttendance },
  ];

  return (
    <div className="space-y-8">
      <SectionHeader title={title} subtitle={subtitle} />

      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {summaryCards.map((card) => (
          <InfoCard key={card.title} title={card.title} value={card.value} />
        ))}
      </div>

      <div className="grid gap-6 xl:grid-cols-[1.15fr_0.85fr]">
        <div className="space-y-6">
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
              <div>
                <h2 className="text-xl font-semibold text-white">Attendance session</h2>
                <p className="text-sm text-slate-400">Configure the academic session and capture daily attendance in one screen.</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <button type="button" onClick={handleMarkAllPresent} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Mark all present</button>
                <button type="button" onClick={handleQuickToggle} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Quick toggle</button>
                <button type="button" onClick={handleBulkAttendance} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Bulk attendance</button>
              </div>
            </div>

            <div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">
              <FormField label="Academic year">
                <input name="academicYear" value={sessionValues.academicYear || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              <FormField label="Campus">
                <input name="campus" value={sessionValues.campus || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              <FormField label="Department">
                <input name="department" value={sessionValues.department || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              {scope === 'student' && (
                <>
                  <FormField label="Course">
                    <input name="course" value={sessionValues.course || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
                  </FormField>
                  <FormField label="Semester">
                    <input name="semester" value={sessionValues.semester || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
                  </FormField>
                  <FormField label="Section">
                    <input name="section" value={sessionValues.section || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
                  </FormField>
                </>
              )}
              <FormField label={scope === 'student' ? 'Subject' : scope === 'teacher' ? 'Subject' : scope === 'employee' ? 'Shift' : 'Post'}>
                <input name={scope === 'student' ? 'subject' : scope === 'teacher' ? 'subject' : scope === 'employee' ? 'shift' : 'post'} value={scope === 'student' ? sessionValues.subject || '' : scope === 'teacher' ? sessionValues.subject || '' : scope === 'employee' ? sessionValues.shift || '' : sessionValues.post || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              <FormField label={scope === 'student' ? 'Faculty' : scope === 'teacher' ? 'Faculty' : scope === 'employee' ? 'Employee' : 'Guard'}>
                <input name={scope === 'student' ? 'faculty' : scope === 'teacher' ? 'faculty' : scope === 'employee' ? 'employeeName' : 'guardName'} value={scope === 'student' ? sessionValues.faculty || '' : scope === 'teacher' ? sessionValues.faculty || '' : scope === 'employee' ? sessionValues.employeeName || '' : sessionValues.guardName || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              <FormField label="Date">
                <input type="date" name="date" value={sessionValues.date || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
              <FormField label="Time slot">
                <input name="timeSlot" value={sessionValues.timeSlot || ''} onChange={handleFieldChange} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              </FormField>
            </div>

            <div className="mt-5 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-950/90">
              <table className="min-w-full text-sm text-slate-300">
                <thead className="bg-slate-800/70 text-slate-300">
                  <tr>
                    <th className="px-4 py-3 text-left">{entityLabel}</th>
                    <th className="px-4 py-3 text-left">Status</th>
                    <th className="px-4 py-3 text-left">Remarks</th>
                  </tr>
                </thead>
                <tbody>
                  {draftEntries.length ? draftEntries.map((entry) => (
                    <tr key={entry.id} className="border-t border-slate-800/70">
                      <td className="px-4 py-3">
                        <div className="font-semibold text-white">{entry.name}</div>
                        <div className="text-xs text-slate-500">{entry.subject || sessionValues.subject || 'ΓÇö'}</div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex flex-wrap gap-2 hover-gradient-border" tabIndex={0} onKeyDown={(event) => {
                          if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            updateDraftStatus(entry.id, entry.status === 'Present' ? 'Absent' : 'Present');
                          }
                        }}>
                          {ATTENDANCE_STATUSES.map((status) => (
                            <button key={`${entry.id}-${status}`} type="button" onClick={() => updateDraftStatus(entry.id, status)} className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${entry.status === status ? getStatusClass(status) : 'bg-slate-700/70 text-slate-200'}`}>
                              {status}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <input value={entry.remarks || ''} onChange={(event) => setDraftEntries((current) => current.map((item) => (item.id === entry.id ? { ...item, remarks: event.target.value } : item)))} className="w-full rounded-2xl border border-slate-700/70 bg-slate-900/80 px-3 py-2 text-sm text-slate-100 outline-none" placeholder="Notes" />
                      </td>
                    </tr>
                  )) : <tr><td colSpan="3" className="px-4 py-6 text-center text-slate-500">No draft entries yet. Use bulk attendance to prefill the register.</td></tr>}
                </tbody>
              </table>
            </div>

            <div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-[18px] border border-slate-800/80 bg-slate-950/80 p-3 text-sm text-slate-300 hover-gradient-border">
              <span>{statusMessage}</span>
              <div className="flex flex-wrap gap-2">
                <button type="button" onClick={handleSubmitAttendance} disabled={isSubmitting || !draftEntries.length} className="inline-flex items-center gap-2 rounded-3xl bg-sky-400 px-4 py-2 font-semibold text-slate-950 transition hover:bg-sky-300 disabled:cursor-not-allowed disabled:opacity-60 hover-gradient-border">
                  <FaSave /> {isSubmitting ? 'Submitting...' : 'Submit attendance'}
                </button>
                <button type="button" onClick={() => loadAttendanceData()} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-slate-200 hover:bg-slate-700">
                  <FaSyncAlt /> Refresh
                </button>
              </div>
            </div>
          </div>

          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
              <div>
                <h2 className="text-xl font-semibold text-white">Attendance history</h2>
                <p className="text-sm text-slate-400">Review monthly trends, leave requests, and subject-wise attendance percentage.</p>
              </div>
              <div className="rounded-3xl border border-slate-700/80 bg-slate-950/80 px-3 py-2 text-sm text-slate-300">Attendance trend {summary.attendancePercentage}%</div>
            </div>
            <div className="mt-5 grid gap-3 md:grid-cols-3">
              <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
                <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Present percentage</p>
                <p className="mt-3 text-2xl font-semibold text-white">{summary.attendancePercentage}%</p>
              </div>
              <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
                <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Leave history</p>
                <p className="mt-3 text-2xl font-semibold text-white">{leaves.length}</p>
              </div>
              <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
                <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Subject breakdown</p>
                <p className="mt-3 text-lg font-semibold text-white">{Object.keys(subjectBreakdown).length} subjects</p>
              </div>
            </div>
            <div className="mt-5 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-950/90">
              <table className="min-w-full text-sm text-slate-300">
                <thead className="bg-slate-800/70 text-slate-400">
                  <tr>
                    <th className="px-4 py-3 text-left">Date</th>
                    <th className="px-4 py-3 text-left">Status</th>
                    <th className="px-4 py-3 text-left">Subject</th>
                    <th className="px-4 py-3 text-left">Remarks</th>
                    <th className="px-4 py-3 text-left">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {history.length ? history.map((entry) => (
                    <tr key={entry.id} className="border-t border-slate-800/70">
                      <td className="px-4 py-3">{entry.date}</td>
                      <td className="px-4 py-3"><StatusBadge status={entry.status} /></td>
                      <td className="px-4 py-3">{entry.subject || 'ΓÇö'}</td>
                      <td className="px-4 py-3">{entry.remarks || 'ΓÇö'}</td>
                      <td className="px-4 py-3"><IconActionButton icon={Trash2} title="Delete record" ariaLabel="Delete record" variant="danger" onClick={() => handleDeleteRecord(entry.id)} /></td>
                    </tr>
                  )) : <tr><td colSpan="5" className="px-4 py-6 text-center text-slate-500">No attendance history yet.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="space-y-6">
          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="mb-4 flex items-center gap-3 hover-gradient-border">
              <div className="flex h-12 w-12 items-center justify-center rounded-3xl bg-slate-700/80 text-slate-200 hover-gradient-border"><FaUserGraduate className="h-5 w-5" /></div>
              <div>
                <p className="text-sm uppercase tracking-[0.24em] text-slate-400">Search & filters</p>
                <h3 className="text-xl font-semibold text-white">Find attendance quickly</h3>
              </div>
            </div>
            <div className="grid gap-3">
              <input value={filters.query} onChange={(event) => setFilters((current) => ({ ...current, query: event.target.value }))} placeholder={`${entityPlaceholder} or student ID, status, subject...`} className="rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
              <SearchFilter search={filters.query} onSearch={(value) => setFilters((current) => ({ ...current, query: value }))} filter={filters.status} onFilter={(value) => setFilters((current) => ({ ...current, status: value }))} options={statusOptions} />
              <div className="grid gap-3 sm:grid-cols-2">
                <FormField label="Course">
                  <input value={filters.course} onChange={(event) => setFilters((current) => ({ ...current, course: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Department">
                  <input value={filters.department} onChange={(event) => setFilters((current) => ({ ...current, department: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Semester">
                  <input value={filters.semester} onChange={(event) => setFilters((current) => ({ ...current, semester: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Faculty">
                  <input value={filters.faculty} onChange={(event) => setFilters((current) => ({ ...current, faculty: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Subject">
                  <input value={filters.subject} onChange={(event) => setFilters((current) => ({ ...current, subject: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Status">
                  <select value={filters.status} onChange={(event) => setFilters((current) => ({ ...current, status: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400">
                    {statusOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                  </select>
                </FormField>
              </div>
              <div className="grid gap-3 sm:grid-cols-2">
                <FormField label="Date from">
                  <input type="date" value={filters.dateFrom} onChange={(event) => setFilters((current) => ({ ...current, dateFrom: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
                <FormField label="Date to">
                  <input type="date" value={filters.dateTo} onChange={(event) => setFilters((current) => ({ ...current, dateTo: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400" />
                </FormField>
              </div>
            </div>
          </div>

          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="flex items-center justify-between gap-3 hover-gradient-border">
              <div>
                <h3 className="text-xl font-semibold text-white">Reports</h3>
                <p className="text-sm text-slate-400">Export, print and review attendance summaries for operations teams.</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <button type="button" onClick={() => setReportMode('Daily')} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700">Daily</button>
                <button type="button" onClick={() => setReportMode('Monthly')} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700">Monthly</button>
                <button type="button" onClick={() => setReportMode('Low Attendance Report')} className="rounded-3xl bg-slate-800/80 px-3 py-2 text-sm text-slate-200 hover:bg-slate-700">Low attendance</button>
              </div>
            </div>
            <div className="mt-4 grid gap-3">
              {reportModes.map((mode) => (
                <button key={mode} type="button" onClick={() => setReportMode(mode)} className={`rounded-[18px] border px-4 py-3 text-left text-sm ${reportMode === mode ? 'border-sky-400 bg-sky-500/10 text-sky-300' : 'border-slate-700/70 bg-slate-950/70 text-slate-300'}`}>
                  {mode}
                </button>
              ))}
            </div>
            <div className="mt-4 flex flex-wrap gap-2">
              <button type="button" onClick={() => handleExport('csv')} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"><FaDownload /> CSV</button>
              <button type="button" onClick={() => handleExport('excel')} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"><FaDownload /> Excel</button>
              <button type="button" onClick={handlePrint} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border"><FaPrint /> Print</button>
            </div>
            <div className="mt-4 rounded-[18px] border border-slate-700/70 bg-slate-950/70 p-4 text-sm text-slate-300">
              <p className="text-xs uppercase tracking-[0.24em] text-slate-500">Current report</p>
              <p className="mt-2 font-semibold text-white">{reportMode}</p>
              <p className="mt-2">{reportRows.length} matching records ΓÇó {formatCurrency(summary.attendancePercentage)} attendance rate</p>
            </div>
          </div>

          <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
            <div className="mb-3 flex items-center justify-between gap-3 hover-gradient-border">
              <div>
                <h3 className="text-xl font-semibold text-white">Leave requests</h3>
                <p className="text-sm text-slate-400">Capture late, absent and medical leave details for review.</p>
              </div>
            </div>
            <form onSubmit={handleCreateLeave} className="space-y-3">
              <input value={sessionValues.studentName || ''} onChange={handleFieldChange} name="studentName" placeholder="Student / staff name" className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              <textarea name="remarks" value={sessionValues.remarks || ''} onChange={handleFieldChange} rows="3" placeholder="Leave reason" className="w-full rounded-3xl border border-white/10 bg-slate-950/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
              <button type="submit" className="rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border">Create leave request</button>
            </form>
            {isLoading ? (
              <div className="mt-4 rounded-[16px] border border-slate-700/70 bg-slate-950/70 p-3 text-sm text-slate-300">
                Loading attendance data...
              </div>
            ) : (
              <div className="mt-4 space-y-2">
                {leaves.slice(0, 4).map((leave) => (
                  <div key={leave.id} className="rounded-[16px] border border-slate-700/70 bg-slate-950/70 p-3 text-sm text-slate-300">
                    <div className="flex items-center justify-between gap-3 hover-gradient-border">
                      <span className="font-semibold text-white">{leave.studentName || leave.employeeName || leave.guardName || 'Leave request'}</span>
                      <StatusBadge status={leave.status || 'Pending'} />
                    </div>
                    <p className="mt-1">{leave.reason || 'Reason pending'}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { FaDownload, FaPlus, FaPrint } from 'react-icons/fa';
import { Edit3, Send } from 'lucide-react';
import SectionHeader from '../ui/SectionHeader.jsx';
import SearchFilter from '../forms/SearchFilter.jsx';
// DataTable not used in this module ΓÇö removed to satisfy lint
import FormField from '../forms/FormField.jsx';
import Modal from '../ui/Modal.jsx';
import Button from '../ui/Button.jsx';
import StatusBadge from '../ui/StatusBadge.jsx';
import IconActionButton from '../ui/IconActionButton.jsx';
import { createExamMaster, createExamSchedule, listExamMasters, listExamSchedules } from '../../services/examService.js';
import { createMarkEntry, listMarkEntries, publishMarkEntries } from '../../services/markEntryService.js';
import { createResult, listResults, publishResult, updateResult } from '../../services/resultService.js';
import { calculateResultMetrics } from '../../services/gradeService.js';

const masterTypes = [
  { value: 'academicYear', label: 'Academic Year' },
  { value: 'examType', label: 'Examination Type' },
];

const statusOptions = [
  { value: 'All', label: 'All statuses' },
  { value: 'Scheduled', label: 'Scheduled' },
  { value: 'Draft', label: 'Draft' },
  { value: 'Published', label: 'Published' },
];

export default function ExaminationModule() {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [masterModalOpen, setMasterModalOpen] = useState(false);
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [markModalOpen, setMarkModalOpen] = useState(false);
  const [resultModalOpen, setResultModalOpen] = useState(false);
  const [masters, setMasters] = useState(listExamMasters().items);
  const [schedules, setSchedules] = useState(listExamSchedules().items);
  const [markEntries, setMarkEntries] = useState(listMarkEntries().items);
  const [results, setResults] = useState(listResults().items);
  const [masterForm, setMasterForm] = useState({ kind: 'examType', name: '', description: '' });
  const [scheduleForm, setScheduleForm] = useState({ examName: '', course: '', department: '', semester: '', subject: '', date: '', startTime: '', endTime: '', room: '', invigilator: '', duration: '' });
  const [markForm, setMarkForm] = useState({ studentName: '', studentId: '', course: '', semester: '', subject: '', internalMarks: '0', externalMarks: '0', practicalMarks: '0', assignmentMarks: '0', attendanceMarks: '0', graceMarks: '0' });
  const [resultForm, setResultForm] = useState({ studentName: '', studentId: '', semester: '', course: '', total: '0', percentage: '0', cgpa: '0', sgpa: '0', grade: '', status: 'Pass' });

  const filteredSchedules = useMemo(() => {
    return schedules.filter((schedule) => {
      const query = search.toLowerCase();
      const matchesSearch = [schedule.examName, schedule.course, schedule.department, schedule.subject, schedule.room, schedule.invigilator].some((value) => (value || '').toLowerCase().includes(query));
      const matchesFilter = filter === 'All' || schedule.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [schedules, search, filter]);

  const filteredMarks = useMemo(() => {
    return markEntries.filter((entry) => {
      const query = search.toLowerCase();
      const matchesSearch = [entry.studentName, entry.studentId, entry.subject, entry.course].some((value) => (value || '').toLowerCase().includes(query));
      const matchesFilter = filter === 'All' || entry.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [markEntries, search, filter]);

  const filteredResults = useMemo(() => {
    return results.filter((entry) => {
      const query = search.toLowerCase();
      const matchesSearch = [entry.studentName, entry.studentId, entry.course].some((value) => (value || '').toLowerCase().includes(query));
      const matchesFilter = filter === 'All' || entry.status === filter;
      return matchesSearch && matchesFilter;
    });
  }, [results, search, filter]);

  const handleCreateMaster = (event) => {
    event.preventDefault();
    const response = createExamMaster(masterForm);
    setMasters((current) => [response.item, ...current]);
    setMasterForm({ kind: 'examType', name: '', description: '' });
    setMasterModalOpen(false);
  };

  const handleCreateSchedule = (event) => {
    event.preventDefault();
    const response = createExamSchedule(scheduleForm);
    setSchedules((current) => [response.item, ...current]);
    setScheduleForm({ examName: '', course: '', department: '', semester: '', subject: '', date: '', startTime: '', endTime: '', room: '', invigilator: '', duration: '' });
    setScheduleModalOpen(false);
  };

  const handleCreateMark = (event) => {
    event.preventDefault();
    const metrics = calculateResultMetrics({
      internal: markForm.internalMarks,
      external: markForm.externalMarks,
      practical: markForm.practicalMarks,
      assignment: markForm.assignmentMarks,
      attendance: markForm.attendanceMarks,
      grace: markForm.graceMarks,
    });
    const payload = {
      ...markForm,
      internalMarks: Number(markForm.internalMarks),
      externalMarks: Number(markForm.externalMarks),
      practicalMarks: Number(markForm.practicalMarks),
      assignmentMarks: Number(markForm.assignmentMarks),
      attendanceMarks: Number(markForm.attendanceMarks),
      graceMarks: Number(markForm.graceMarks),
      ...metrics,
      status: 'Draft',
    };
    const response = createMarkEntry(payload);
    setMarkEntries((current) => [response.item, ...current]);
    setMarkForm({ studentName: '', studentId: '', course: '', semester: '', subject: '', internalMarks: '0', externalMarks: '0', practicalMarks: '0', assignmentMarks: '0', attendanceMarks: '0', graceMarks: '0' });
    setMarkModalOpen(false);
  };

  const handlePublishMarks = () => {
    const ids = markEntries.filter((entry) => entry.status === 'Draft').map((entry) => entry.id);
    const response = publishMarkEntries(ids);
    setMarkEntries(response.items);
  };

  const handleCreateResult = (event) => {
    event.preventDefault();
    const response = createResult({
      ...resultForm,
      total: Number(resultForm.total),
      percentage: Number(resultForm.percentage),
      cgpa: Number(resultForm.cgpa),
      sgpa: Number(resultForm.sgpa),
      status: resultForm.status || 'Pass',
    });
    setResults((current) => [response.item, ...current]);
    setResultForm({ studentName: '', studentId: '', semester: '', course: '', total: '0', percentage: '0', cgpa: '0', sgpa: '0', grade: '', status: 'Pass' });
    setResultModalOpen(false);
  };

  const handlePublishResult = (id) => {
    const response = publishResult(id);
    setResults(response.items);
  };

  const handleEditResult = (entry) => {
    const response = updateResult(entry.id, { status: 'Edited' });
    setResults(response.items);
  };

  return (
    <div className="space-y-8">
      <SectionHeader title="Examination & result management" subtitle="Manage exam masters, scheduling, mark entry, result processing and reports from a single enterprise view." />

      <div className="grid gap-4 md:grid-cols-3">
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Exam masters</p>
          <p className="mt-3 text-2xl font-semibold text-white">{masters.length}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Scheduled exams</p>
          <p className="mt-3 text-2xl font-semibold text-white">{schedules.length}</p>
        </div>
        <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
          <p className="text-xs uppercase tracking-[0.24em] text-slate-400">Published results</p>
          <p className="mt-3 text-2xl font-semibold text-white">{results.filter((result) => result.published).length}</p>
        </div>
      </div>

      <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Exam master & scheduling</h2>
            <p className="text-sm text-slate-400">Create academic years, exam types, and exam schedules that stay ready for backend integration.</p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={() => setMasterModalOpen(true)} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"><FaPlus /> Add master</button>
            <button type="button" onClick={() => setScheduleModalOpen(true)} className="inline-flex items-center gap-2 rounded-3xl bg-sky-400 px-4 py-2 text-sm font-semibold text-slate-950 hover:bg-sky-300"><FaPlus /> Schedule exam</button>
          </div>
        </div>

        <div className="mt-5 grid gap-4 lg:grid-cols-2">
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <h3 className="text-lg font-semibold text-white">Exam masters</h3>
            <div className="mt-4 space-y-2">
              {masters.map((master) => (
                <div key={master.id} className="rounded-[16px] border border-slate-700/70 bg-slate-900/80 p-3">
                  <div className="flex items-center justify-between gap-3 hover-gradient-border">
                    <div>
                      <p className="font-semibold text-white">{master.name}</p>
                      <p className="text-sm text-slate-400">{master.description || master.kind}</p>
                    </div>
                    <StatusBadge status={master.kind === 'academicYear' ? 'Scheduled' : 'Published'} />
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="rounded-[20px] border border-slate-700/60 bg-slate-950/90 p-4">
            <h3 className="text-lg font-semibold text-white">Exam schedules</h3>
            <div className="mt-4 space-y-2">
              {filteredSchedules.map((schedule) => (
                <div key={schedule.id} className="rounded-[16px] border border-slate-700/70 bg-slate-900/80 p-3">
                  <div className="flex items-center justify-between gap-3 hover-gradient-border">
                    <div>
                      <p className="font-semibold text-white">{schedule.examName}</p>
                      <p className="text-sm text-slate-400">{schedule.course} ΓÇó {schedule.department} ΓÇó {schedule.date}</p>
                    </div>
                    <StatusBadge status={schedule.status || 'Scheduled'} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Mark entry</h2>
            <p className="text-sm text-slate-400">Capture internal, external, practical, assignment, attendance and grace marks with draft and publish controls.</p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={() => setMarkModalOpen(true)} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"><FaPlus /> New mark entry</button>
            <button type="button" onClick={handlePublishMarks} className="inline-flex items-center gap-2 rounded-3xl bg-emerald-400 px-4 py-2 text-sm font-semibold text-slate-950 hover:bg-emerald-300 hover-gradient-border">Publish drafts</button>
          </div>
        </div>

        <div className="mt-4"><SearchFilter search={search} onSearch={setSearch} filter={filter} onFilter={setFilter} options={statusOptions} /></div>
        <div className="mt-4 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-950/90">
          <table className="min-w-full text-sm text-slate-300">
            <thead className="bg-slate-800/70 text-slate-400">
              <tr>
                <th className="px-4 py-3 text-left">Student</th>
                <th className="px-4 py-3 text-left">Subject</th>
                <th className="px-4 py-3 text-left">Total</th>
                <th className="px-4 py-3 text-left">Grade</th>
                <th className="px-4 py-3 text-left">Result</th>
                <th className="px-4 py-3 text-left">Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredMarks.map((entry) => (
                <tr key={entry.id} className="border-t border-slate-800/70">
                  <td className="px-4 py-3"><div className="font-semibold text-white">{entry.studentName}</div><div className="text-xs text-slate-500">{entry.studentId}</div></td>
                  <td className="px-4 py-3">{entry.subject}</td>
                  <td className="px-4 py-3">{entry.total}</td>
                  <td className="px-4 py-3">{entry.grade}</td>
                  <td className="px-4 py-3">{entry.result}</td>
                  <td className="px-4 py-3"><StatusBadge status={entry.status} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="rounded-[24px] border border-white/10 bg-slate-900/80 p-4 shadow-sm">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h2 className="text-xl font-semibold text-white">Result processing & student results</h2>
            <p className="text-sm text-slate-400">Process marks into results, calculate performance metrics, and publish results for student access.</p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={() => setResultModalOpen(true)} className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"><FaPlus /> Add result</button>
            <button type="button" className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border"><FaDownload /> Export</button>
            <button type="button" className="inline-flex items-center gap-2 rounded-3xl bg-slate-800/80 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700 hover-gradient-border"><FaPrint /> Print</button>
          </div>
        </div>
        <div className="mt-4 overflow-x-auto rounded-[20px] border border-slate-700/60 bg-slate-950/90">
          <table className="min-w-full text-sm text-slate-300">
            <thead className="bg-slate-800/70 text-slate-400">
              <tr>
                <th className="px-4 py-3 text-left">Student</th>
                <th className="px-4 py-3 text-left">Semester</th>
                <th className="px-4 py-3 text-left">Total</th>
                <th className="px-4 py-3 text-left">SGPA</th>
                <th className="px-4 py-3 text-left">CGPA</th>
                <th className="px-4 py-3 text-left">Result</th>
                <th className="px-4 py-3 text-left">Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredResults.map((entry) => (
                <tr key={entry.id} className="border-t border-slate-800/70">
                  <td className="px-4 py-3"><div className="font-semibold text-white">{entry.studentName}</div><div className="text-xs text-slate-500">{entry.studentId}</div></td>
                  <td className="px-4 py-3">{entry.semester}</td>
                  <td className="px-4 py-3">{entry.total}</td>
                  <td className="px-4 py-3">{entry.sgpa}</td>
                  <td className="px-4 py-3">{entry.cgpa}</td>
                  <td className="px-4 py-3"><StatusBadge status={entry.status} /></td>
                  <td className="px-4 py-3">
                    <div className="flex flex-wrap gap-2">
                      <IconActionButton icon={Send} title="Publish result" ariaLabel="Publish result" variant="success" onClick={() => handlePublishResult(entry.id)} className="h-8 w-8" />
                      <IconActionButton icon={Edit3} title="Edit result" ariaLabel="Edit result" onClick={() => handleEditResult(entry)} className="h-8 w-8" />
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal title="Create exam master" isOpen={masterModalOpen} onClose={() => setMasterModalOpen(false)} footer={<button onClick={handleCreateMaster} variant="primary" className="hover-gradient-border">Save master</button>}>
        <form className="space-y-4" onSubmit={handleCreateMaster}>
          <FormField label="Type">
            <select value={masterForm.kind} onChange={(event) => setMasterForm((current) => ({ ...current, kind: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none">
              {masterTypes.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
            </select>
          </FormField>
          <FormField label="Name"><input value={masterForm.name} onChange={(event) => setMasterForm((current) => ({ ...current, name: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" placeholder="Academic year or exam type" /></FormField>
          <FormField label="Description"><textarea value={masterForm.description} onChange={(event) => setMasterForm((current) => ({ ...current, description: event.target.value }))} rows="3" className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
        </form>
      </Modal>

      <Modal title="Schedule exam" isOpen={scheduleModalOpen} onClose={() => setScheduleModalOpen(false)} footer={<button onClick={handleCreateSchedule} variant="primary" className="hover-gradient-border">Save schedule</button>}>
        <form className="grid gap-4 lg:grid-cols-2" onSubmit={handleCreateSchedule}>
          <FormField label="Exam name"><input value={scheduleForm.examName} onChange={(event) => setScheduleForm((current) => ({ ...current, examName: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Course"><input value={scheduleForm.course} onChange={(event) => setScheduleForm((current) => ({ ...current, course: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Department"><input value={scheduleForm.department} onChange={(event) => setScheduleForm((current) => ({ ...current, department: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Semester"><input value={scheduleForm.semester} onChange={(event) => setScheduleForm((current) => ({ ...current, semester: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Subject"><input value={scheduleForm.subject} onChange={(event) => setScheduleForm((current) => ({ ...current, subject: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Date"><input type="date" value={scheduleForm.date} onChange={(event) => setScheduleForm((current) => ({ ...current, date: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Start time"><input value={scheduleForm.startTime} onChange={(event) => setScheduleForm((current) => ({ ...current, startTime: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="End time"><input value={scheduleForm.endTime} onChange={(event) => setScheduleForm((current) => ({ ...current, endTime: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Room"><input value={scheduleForm.room} onChange={(event) => setScheduleForm((current) => ({ ...current, room: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Invigilator"><input value={scheduleForm.invigilator} onChange={(event) => setScheduleForm((current) => ({ ...current, invigilator: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Duration"><input value={scheduleForm.duration} onChange={(event) => setScheduleForm((current) => ({ ...current, duration: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
        </form>
      </Modal>

      <Modal title="Add mark entry" isOpen={markModalOpen} onClose={() => setMarkModalOpen(false)} footer={<button onClick={handleCreateMark} variant="primary" className="hover-gradient-border">Save marks</button>}>
        <form className="grid gap-4 lg:grid-cols-2" onSubmit={handleCreateMark}>
          <FormField label="Student name"><input value={markForm.studentName} onChange={(event) => setMarkForm((current) => ({ ...current, studentName: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Student ID"><input value={markForm.studentId} onChange={(event) => setMarkForm((current) => ({ ...current, studentId: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Course"><input value={markForm.course} onChange={(event) => setMarkForm((current) => ({ ...current, course: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Semester"><input value={markForm.semester} onChange={(event) => setMarkForm((current) => ({ ...current, semester: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Subject"><input value={markForm.subject} onChange={(event) => setMarkForm((current) => ({ ...current, subject: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Internal marks"><input type="number" value={markForm.internalMarks} onChange={(event) => setMarkForm((current) => ({ ...current, internalMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="External marks"><input type="number" value={markForm.externalMarks} onChange={(event) => setMarkForm((current) => ({ ...current, externalMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Practical marks"><input type="number" value={markForm.practicalMarks} onChange={(event) => setMarkForm((current) => ({ ...current, practicalMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Assignment marks"><input type="number" value={markForm.assignmentMarks} onChange={(event) => setMarkForm((current) => ({ ...current, assignmentMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Attendance marks"><input type="number" value={markForm.attendanceMarks} onChange={(event) => setMarkForm((current) => ({ ...current, attendanceMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Grace marks"><input type="number" value={markForm.graceMarks} onChange={(event) => setMarkForm((current) => ({ ...current, graceMarks: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
        </form>
      </Modal>

      <Modal title="Create result" isOpen={resultModalOpen} onClose={() => setResultModalOpen(false)} footer={<button onClick={handleCreateResult} variant="primary" className="hover-gradient-border">Save result</button>}>
        <form className="grid gap-4 lg:grid-cols-2" onSubmit={handleCreateResult}>
          <FormField label="Student name"><input value={resultForm.studentName} onChange={(event) => setResultForm((current) => ({ ...current, studentName: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Student ID"><input value={resultForm.studentId} onChange={(event) => setResultForm((current) => ({ ...current, studentId: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Course"><input value={resultForm.course} onChange={(event) => setResultForm((current) => ({ ...current, course: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Semester"><input value={resultForm.semester} onChange={(event) => setResultForm((current) => ({ ...current, semester: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Total"><input type="number" value={resultForm.total} onChange={(event) => setResultForm((current) => ({ ...current, total: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Percentage"><input type="number" value={resultForm.percentage} onChange={(event) => setResultForm((current) => ({ ...current, percentage: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="CGPA"><input type="number" value={resultForm.cgpa} onChange={(event) => setResultForm((current) => ({ ...current, cgpa: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="SGPA"><input type="number" value={resultForm.sgpa} onChange={(event) => setResultForm((current) => ({ ...current, sgpa: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Grade"><input value={resultForm.grade} onChange={(event) => setResultForm((current) => ({ ...current, grade: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none" /></FormField>
          <FormField label="Status"><select value={resultForm.status} onChange={(event) => setResultForm((current) => ({ ...current, status: event.target.value }))} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none"><option value="Pass">Pass</option><option value="Fail">Fail</option></select></FormField>
        </form>
      </Modal>
    </div>
  );
}

