        </div>
        <div className="rounded-2xl bg-rose-50 p-3 text-rose-600">
          <Cake className="h-5 w-5" />
        </div>
      </div>
      <div className="mt-4 max-h-[400px] space-y-3 overflow-y-auto pr-1">
