              <div className="mt-1 flex flex-wrap items-center gap-3 text-xs text-slate-500 hover-gradient-border">
                <span className="flex items-center gap-1 hover-gradient-border"><GraduationCap className="h-3.5 w-3.5" />{student.college}</span>
                <span className="flex items-center gap-1 hover-gradient-border"><BadgeCheck className="h-3.5 w-3.5" />{student.course}</span>
                <span>{student.semester}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

