    if (isEditGuard && selectedGuard) {
      updateGuard.mutate({ id: selectedGuard.id, payload }, {
        onSuccess: () => {
          resetGuardForm();
          setIsGuardModalOpen(false);
        },
      });
    } else {
      createGuard.mutate(payload, {
        onSuccess: () => {
          resetGuardForm();
          setIsGuardModalOpen(false);
          setGuardPage(1);
        },
      });
    }
  };

  const handleDeleteGuard = (guard) => {
