    const subjects = [
      { name: 'Discrete Mathematics', teacher: 'Dr. Ravindra Kr Arya' },
      { name: 'Operating System', teacher: 'Dr. Narayan Jee' },
      { name: 'Operating System Practical', teacher: 'Dr. Bina Singh' },
