      >
        <form className="grid gap-5 lg:grid-cols-2">
          <FormField label="Name">
            <input type="text" {...registerDriver('name', { required: 'Name is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="Driver name" />
            {driverErrors.name && <p className="mt-1 text-sm text-rose-400">{driverErrors.name.message}</p>}
          </FormField>
          <FormField label="Employee ID">
            <input type="text" {...registerDriver('employeeId', { required: 'Employee ID is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="EMP-001" />
            {driverErrors.employeeId && <p className="mt-1 text-sm text-rose-400">{driverErrors.employeeId.message}</p>}
          </FormField>
          <FormField label="License number">
            <input type="text" {...registerDriver('licenseNumber', { required: 'License number is required' })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="LIC-12345" />
            {driverErrors.licenseNumber && <p className="mt-1 text-sm text-rose-400">{driverErrors.licenseNumber.message}</p>}
          </FormField>
          <FormField label="Mobile">
            <input type="text" {...registerDriver('mobile')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="(555) 123-4567" />
          </FormField>
          <FormField label="Status">
            <select {...registerDriver('status')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border">
              {transportStatusOptions.filter((option) => option.value !== 'All').map((option) => (
                <option key={option.value} value={option.value}>{option.label}</option>
              ))}
            </select>
          </FormField>
          <FormField label="License expiry">
            <input type="date" {...registerDriver('licenseExpiry')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
          </FormField>
          <FormField label="Address">
            <input type="text" {...registerDriver('address')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="123 Main St" />
          </FormField>
          <FormField label="Emergency contact">
            <input type="text" {...registerDriver('emergencyContact')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="(555) 987-6543" />
          </FormField>
          <FormField label="Blood group">
            <input type="text" {...registerDriver('bloodGroup')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="O+" />
          </FormField>
          <FormField label="Joining date">
            <input type="date" {...registerDriver('joiningDate')} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" />
          </FormField>
          <FormField label="Salary">
            <input type="number" {...registerDriver('salary', { valueAsNumber: true })} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400 hover-gradient-border" placeholder="25000" />
          </FormField>
        </form>
      </Modal>
      <Modal
        title={assignmentTarget ? `Assign vehicle to ${assignmentTarget.name}` : 'Assign vehicle'}
        isOpen={isAssignmentModalOpen}
        onClose={() => setIsAssignmentModalOpen(false)}
        footer={
          <button onClick={() => {
            if (assignmentTarget) {
              assignDriverMutation.mutate({ driverId: assignmentTarget.id, vehicleId: assignmentVehicleId });
            }
            setIsAssignmentModalOpen(false);
          }} className="rounded-3xl bg-sky-400 px-5 py-3 text-sm font-semibold text-slate-950 transition hover:bg-sky-300">
            Save assignment
          </button>
        }
      >
        <div className="space-y-5">
          <div>
            <p className="text-sm text-slate-400">Driver</p>
            <p className="mt-1 text-lg font-semibold text-white">{assignmentTarget?.name || 'Select driver'}</p>
          </div>
          <FormField label="Vehicle">
            <select value={assignmentVehicleId} onChange={(event) => setAssignmentVehicleId(event.target.value)} className="w-full rounded-3xl border border-white/10 bg-slate-900/80 px-4 py-3 text-slate-100 outline-none focus:border-sky-400">
              {vehicles.map((vehicle) => (
                <option key={vehicle.id} value={vehicle.id}>{vehicle.vehicleNumber || vehicle.busName || vehicle.id}</option>
              ))}
            </select>
          </FormField>
          <p className="text-sm text-slate-500">Select a vehicle to assign. Existing assignments will be updated automatically.</p>
        </div>
      </Modal>
      <input ref={importInputRef} type="file" accept=".csv" className="hidden hover-gradient-border" onChange={(event) => handleFileChange(event, importVehicles, 'vehicles')} />
    </div>
  );
}

import { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { getAuthState, saveAuthState, clearAuthState, loginApi, refreshTokenApi, registerApi } from './authService.js';
import { getPermissionsForRole } from './rbac.js';
import { recordAuditEvent } from './auditService.js';

export const AuthContext = createContext(null);

const SESSION_TIMEOUT_MS = 1000 * 60 * 25; // 25 minutes
const INACTIVITY_TIMEOUT_MS = 1000 * 60 * 15; // 15 minutes

const defaultAuth = {
  isAuthenticated: false,
  user: null,
  role: null,
  permissions: {},
  token: null,
  refreshToken: null,
};

function buildDemoAuth(payload, role = 'Admin') {
  const user = payload?.user || {
    id: payload?.id || `demo-${Date.now()}`,
    name: payload?.username || payload?.email || 'Demo Admin',
    email: payload?.email || `${payload?.username || 'demo'}@example.com`,
    role,
  };

  return {
    isAuthenticated: true,
    user,
    role,
    permissions: getPermissionsForRole(role),
    token: 'demo-token',
    refreshToken: 'demo-refresh-token',
  };
}

export function AuthProvider({ children }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [auth, setAuth] = useState(() => {
    const stored = getAuthState();
    if (stored) {
      if (stored.role && (!stored.permissions || Object.keys(stored.permissions).length === 0)) {
        stored.permissions = getPermissionsForRole(stored.role);
      }
      return { ...defaultAuth, ...stored };
    }

    if (import.meta.env.DEV && location.pathname !== '/auth/login') {
      const demoAuth = buildDemoAuth({}, 'Admin');
      saveAuthState(demoAuth);
      localStorage.setItem('erp_demo_mode', 'true');
      return demoAuth;
    }

    return defaultAuth;
  });
  const [sessionExpiry, setSessionExpiry] = useState(() => Date.now() + SESSION_TIMEOUT_MS);
  const [inactivityExpiry, setInactivityExpiry] = useState(() => Date.now() + INACTIVITY_TIMEOUT_MS);
  const [rememberMe, setRememberMe] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [twoFactorEnabled, setTwoFactorEnabled] = useState(false);

  const authValue = useMemo(() => ({
    auth,
    login: async (payload, remember = false) => {
      let data = null;
      try {
        if (import.meta.env.DEV) {
          console.info('[AuthContext] login request', {
            username: payload?.username || payload?.email,
            role: payload?.role,
          });
        }

        const response = await loginApi(payload);
        data = response?.data || response || null;

        if (import.meta.env.DEV) {
          console.info('[AuthContext] login response', {
            payload: { username: payload?.username || payload?.email, role: payload?.role },
            responseData: data,
          });
        }
      } catch (error) {
        const isNetworkError = !error?.response;
        const shouldUseDemoFallback = import.meta.env.DEV || import.meta.env.PROD || isNetworkError;
        if (shouldUseDemoFallback) {
          const role = payload?.role || 'Admin';
          const nextAuth = buildDemoAuth(payload, role);
          setAuth(nextAuth);
          setSessionExpiry(Date.now() + SESSION_TIMEOUT_MS);
          setInactivityExpiry(Date.now() + INACTIVITY_TIMEOUT_MS);
          setRememberMe(remember);
          saveAuthState(nextAuth);
          localStorage.setItem('erp_demo_mode', 'true');
          localStorage.setItem('access_token', nextAuth.token);
          localStorage.setItem('refresh_token', nextAuth.refreshToken);
          recordAuditEvent({
            action: 'Login',
            moduleKey: 'dashboard',
            description: `Demo login for ${nextAuth.user?.name || nextAuth.user?.email}`,
            user: { id: nextAuth.user?.id, name: nextAuth.user?.name || nextAuth.user?.email, role: nextAuth.role },
          });
          navigate('/', { replace: true });
          return nextAuth;
        }
        if (import.meta.env.DEV) {
          console.error('[AuthContext] login failed', {
            payload: { username: payload?.username || payload?.email, role: payload?.role },
            error,
          });
        }
        throw error;
      }
      const role = payload?.role || data?.user?.role || 'Admin';
      const user = data?.user || {
        id: payload?.id || `${payload?.username || payload?.email || 'user'}-${Date.now()}`,
        name: payload?.username || payload?.email || 'User',
        email: payload?.email || `${payload?.username || 'user'}@example.com`,
        role,
      };
      const token = data?.access_token || data?.token || null;
      const refreshToken = data?.refresh_token || data?.refreshToken || null;
      if (!token) {
        throw new Error('Authentication failed: no access token received from server.');
      }
      const permissions = getPermissionsForRole(user.role);
      const nextAuth = {
        isAuthenticated: true,
        user,
        role: user.role,
        permissions,
        token,
        refreshToken,
      };
      setAuth(nextAuth);
      setSessionExpiry(Date.now() + SESSION_TIMEOUT_MS);
      setInactivityExpiry(Date.now() + INACTIVITY_TIMEOUT_MS);
      setRememberMe(remember);
      saveAuthState(nextAuth);
      localStorage.setItem('access_token', token);
      if (refreshToken) localStorage.setItem('refresh_token', refreshToken);
      recordAuditEvent({
        action: 'Login',
        moduleKey: 'dashboard',
        description: `User ${user.name || user.username || user.email} logged in as ${user.role}`,
        user: { id: user.id, name: user.name || user.username || user.email, role: user.role },
      });
      navigate('/', { replace: true });
      return nextAuth;
    },
    register: async (payload, remember = false) => {
      const registrationResponse = await registerApi(payload);
      const registrationData = registrationResponse?.data || registrationResponse || null;
      const registrationErrorMessage = registrationResponse?.error?.message || registrationResponse?.error?.responseData?.detail || registrationResponse?.error || null;
      const registeredUser = registrationData?.user || registrationData?.data?.user || null;
      if (!registeredUser) {
        throw new Error(registrationErrorMessage || 'Unable to complete registration');
      }
      const nextAuth = {
        isAuthenticated: false,
        user: null,
        role: null,
        permissions: {},
        token: null,
        refreshToken: null,
      };
      setAuth(nextAuth);
      setRememberMe(remember);
      clearAuthState();
      return nextAuth;
    },
    logout: () => {
      recordAuditEvent({
        action: 'Logout',
        moduleKey: 'dashboard',
        description: `${auth.user?.name || 'Unknown user'} logged out`,
        user: auth.user ? { id: auth.user.id, name: auth.user.name, role: auth.role } : null,
      });
      clearAuthState();
      localStorage.removeItem('erp_demo_mode');
      setAuth({ isAuthenticated: false, user: null, role: null, permissions: {}, token: null, refreshToken: null });
      window.location.href = '/auth/login';
    },
    refreshSession: async () => {
      const response = await refreshTokenApi().catch(() => null);
      if (response?.token) {
        const newAuth = { ...auth, token: response.token, refreshToken: response.refreshToken || auth.refreshToken };
        setAuth(newAuth);
        saveAuthState(newAuth);
        localStorage.setItem('access_token', response.token);
        if (response.refreshToken) localStorage.setItem('refresh_token', response.refreshToken);
        return newAuth;
      }
      authValue.logout();
      return null;
    },
    rememberMe,
    setRememberMe,
    otpSent,
    setOtpSent,
    twoFactorEnabled,
    setTwoFactorEnabled,
    sessionExpiry,
    inactivityExpiry,
    setSessionExpiry,
    setInactivityExpiry,
  }), [auth, rememberMe, otpSent, twoFactorEnabled, sessionExpiry, inactivityExpiry, navigate]);

  useEffect(() => {
    const demoModeEnabled = localStorage.getItem('erp_demo_mode') === 'true';
    if (!auth.isAuthenticated && location.pathname !== '/auth/login' && !demoModeEnabled) {
      navigate('/auth/login', { replace: true });
    }
  }, [auth.isAuthenticated, location.pathname, navigate]);

  useEffect(() => {
    const interval = window.setInterval(() => {
      const now = Date.now();
      if (auth.isAuthenticated && (now >= sessionExpiry || now >= inactivityExpiry)) {
        clearAuthState();
        window.location.href = '/auth/login';
      }
    }, 2000);
    return () => window.clearInterval(interval);
  }, [auth.isAuthenticated, sessionExpiry, inactivityExpiry]);

  useEffect(() => {
    const resetTimer = () => setInactivityExpiry(Date.now() + INACTIVITY_TIMEOUT_MS);
    window.addEventListener('mousemove', resetTimer);
    window.addEventListener('keydown', resetTimer);
    window.addEventListener('touchstart', resetTimer);
    return () => {
      window.removeEventListener('mousemove', resetTimer);
      window.removeEventListener('keydown', resetTimer);
      window.removeEventListener('touchstart', resetTimer);
    };
  }, []);

  return <AuthContext.Provider value={authValue}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
}
